//! Traduções: português (Brasil), inglês, espanhol e alemão.
//!
//! O idioma segue o da interface do sistema; se não for nenhum desses, usa
//! inglês. O texto em português é a chave: `tr("Configurações")` devolve a
//! versão no idioma atual. (Para testar: variável `TASKBEAT_LANG=en|es|de|pt`.)

use crate::config::Language;
use std::collections::HashMap;
use std::sync::OnceLock;
use std::sync::atomic::{AtomicU8, Ordering};
#[cfg(windows)]
use windows::Win32::Globalization::GetUserDefaultUILanguage;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Lang {
    Pt,
    En,
    Es,
    De,
}

/// Escolha manual do usuário (0 = automático).
static CHOSEN: AtomicU8 = AtomicU8::new(0);

/// Aplica a opção "Idioma" das configurações (vale na hora).
pub fn apply(l: Language) {
    let v = match l {
        Language::Auto => 0,
        Language::Pt => 1,
        Language::En => 2,
        Language::Es => 3,
        Language::De => 4,
    };
    CHOSEN.store(v, Ordering::Relaxed);
}

pub fn lang() -> Lang {
    match CHOSEN.load(Ordering::Relaxed) {
        1 => return Lang::Pt,
        2 => return Lang::En,
        3 => return Lang::Es,
        4 => return Lang::De,
        _ => {}
    }
    static LANG: OnceLock<Lang> = OnceLock::new();
    *LANG.get_or_init(|| {
        if let Ok(v) = std::env::var("TASKBEAT_LANG") {
            match v.to_ascii_lowercase().get(..2) {
                Some("pt") => return Lang::Pt,
                Some("es") => return Lang::Es,
                Some("de") => return Lang::De,
                Some("en") => return Lang::En,
                _ => {}
            }
        }
        system_lang()
    })
}

/// Idioma da interface do Windows.
#[cfg(windows)]
fn system_lang() -> Lang {
    // Idioma primário = 10 bits baixos do LANGID.
    match unsafe { GetUserDefaultUILanguage() } & 0x3ff {
        0x16 => Lang::Pt,
        0x0a => Lang::Es,
        0x07 => Lang::De,
        _ => Lang::En,
    }
}

/// Primeiro idioma da lista de Ajustes do Sistema > Geral > Idioma e Região.
#[cfg(target_os = "macos")]
fn system_lang() -> Lang {
    let first = objc2_foundation::NSLocale::preferredLanguages().firstObject().map(|s| s.to_string()).unwrap_or_default();
    match first.to_ascii_lowercase().get(..2) {
        Some("pt") => Lang::Pt,
        Some("es") => Lang::Es,
        Some("de") => Lang::De,
        _ => Lang::En,
    }
}

/// Idioma da sessão (variáveis de localidade, na ordem que o gettext usa).
#[cfg(target_os = "linux")]
fn system_lang() -> Lang {
    let first = ["LANGUAGE", "LC_ALL", "LC_MESSAGES", "LANG"]
        .iter()
        .filter_map(|k| std::env::var(k).ok())
        .flat_map(|v| v.split(':').map(str::to_string).collect::<Vec<_>>())
        .find(|v| !v.is_empty() && v != "C" && v != "POSIX" && !v.starts_with("C."))
        .unwrap_or_default();
    match first.to_ascii_lowercase().get(..2) {
        Some("pt") => Lang::Pt,
        Some("es") => Lang::Es,
        Some("de") => Lang::De,
        _ => Lang::En,
    }
}

/// Texto no idioma atual (a chave é o texto em português).
pub fn tr(pt: &'static str) -> &'static str {
    static MAP: OnceLock<HashMap<&'static str, &'static [&'static str; 4]>> = OnceLock::new();
    let col = match lang() {
        Lang::Pt => return pt,
        Lang::En => 1,
        Lang::Es => 2,
        Lang::De => 3,
    };
    let map = MAP.get_or_init(|| T.iter().chain(lyrics_t::T).map(|r| (r[0], r)).collect());
    match map.get(pt) {
        Some(r) => r[col],
        None => pt,
    }
}

#[cfg(test)]
pub fn has(pt: &str) -> bool {
    T.iter().chain(lyrics_t::T).any(|r| r[0] == pt)
}

